<?php
declare(strict_types=1);
namespace Brebo\Office\Project\Workspace;
use PDO;
require_once __DIR__.'/Tasks.php';
final class Controls {
  use Tasks;
  public function __construct(private readonly PDO $db,private readonly string $actor){}
  public function authorize(int $project,bool $write=false):void{
    if($project<1||!ctype_digit($this->actor))throw new \DomainException('Project niet beschikbaar.');$q=$this->db->prepare("SELECT 1 FROM office_project_memberships m JOIN office_operator_accounts a ON a.id=m.operator_id JOIN office_projects p ON p.id=m.project_id WHERE m.project_id=? AND m.operator_id=? AND a.active=1 AND ".($write?"m.permission='manage'":"m.permission IN ('read','manage')"));$q->execute([$project,$this->actor]);if(!$q->fetchColumn())throw new \DomainException('Geen toegang tot dit project.');
  }
  public function finance(bool $write=false):bool{$q=$this->db->prepare("SELECT permission FROM office_module_permissions WHERE operator_id=? AND module='finance'");$q->execute([$this->actor]);$permissions=$q->fetchAll(PDO::FETCH_COLUMN);return in_array('read',$permissions,true)&&(!$write||in_array('draft_edit',$permissions,true));}
  public static function date(mixed $v,bool $optional=false):?string{if($optional&&($v===null||$v===''))return null;if(!is_string($v))throw new \InvalidArgumentException('Ongeldige datum.');$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$v,new \DateTimeZone('UTC'));if(!$d||$d->format('Y-m-d')!==$v)throw new \InvalidArgumentException('Ongeldige datum.');return $v;}
  public static function text(mixed $v,int $max=255,bool $optional=false):string{if(!is_string($v)||strlen(trim($v))>$max||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/',$v)||(!$optional&&trim($v)===''))throw new \InvalidArgumentException('Vul een geldige omschrijving of onderbouwing in.');return trim($v);}
  public static function number(mixed $v,int $min=0,int $max=2147483647):int{$n=filter_var($v,FILTER_VALIDATE_INT,['options'=>['min_range'=>$min,'max_range'=>$max]]);if(!is_int($n))throw new \InvalidArgumentException('Ongeldig getal.');return $n;}
  public static function cents(mixed $v):int{if(!is_string($v)||!preg_match('/^\d{1,10}(?:[.,]\d{1,2})?$/D',trim($v)))throw new \InvalidArgumentException('Bedrag: maximaal twee decimalen.');[$a,$b]=array_pad(explode('.',str_replace(',','.',trim($v))),2,'');return (int)$a*100+(int)str_pad($b,2,'0');}
  public static function percent(mixed $v):int{$n=self::cents($v);if($n>10000)throw new \InvalidArgumentException('Percentage moet tussen 0 en 100 liggen.');return $n;}
  public static function token(string $session,string $secret):string{if($session===''||strlen($secret)<32)throw new \RuntimeException('Formulierbeveiliging ontbreekt.');return hash_hmac('sha256','project-workspace-v1|'.$session,$secret);}
  private function transaction(int $project,callable $f):mixed{
    $this->authorize($project,true);$this->db->beginTransaction();try{$lock=$this->db->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'';$q=$this->db->prepare('SELECT id FROM office_projects WHERE id=?'.$lock);$q->execute([$project]);if(!$q->fetchColumn())throw new \DomainException('Project ontbreekt.');$result=$f();$this->db->commit();return $result;}catch(\Throwable $e){$this->db->rollBack();throw $e;}
  }
  private function audit(int $project,string $event,?int $id,array $detail):void{$this->db->prepare('INSERT INTO office_project_control_audit(project_id,operator_id,event,entity_id,detail_json,created_at) VALUES(?,?,?,?,?,?)')->execute([$project,$this->actor,$event,$id,json_encode($detail,JSON_THROW_ON_ERROR),gmdate('c')]);}
  public function settings(int $project):?array{$this->authorize($project);$q=$this->db->prepare('SELECT * FROM office_project_control_settings WHERE project_id=?');$q->execute([$project]);return $q->fetch(PDO::FETCH_ASSOC)?:null;}
  public function save(int $project,int $revision,array $input,string $today):void{
    self::date($today);$dates=[];foreach(['planned_start','planned_end','actual_start','actual_end'] as $k)$dates[$k]=self::date($input[$k]??null,true);foreach([['planned_start','planned_end'],['actual_start','actual_end']] as [$a,$b])if($dates[$a]&&$dates[$b]&&$dates[$b]<$dates[$a])throw new \InvalidArgumentException('Einddatum ligt voor de startdatum.');foreach(['actual_start','actual_end'] as $k)if($dates[$k]&&$dates[$k]>$today)throw new \InvalidArgumentException('Werkelijke datums kunnen niet in de toekomst liggen.');$note=self::text($input['scope_note']??'',5000,true);
    $this->transaction($project,function()use($project,$revision,$dates,$note){$old=$this->settings($project);if((int)($old['revision']??0)!==$revision)throw new \DomainException('Projectgegevens gewijzigd; laad opnieuw.');$values=[...array_values($dates),$note,$revision+1,$this->actor,gmdate('c')];if($old)$this->db->prepare('UPDATE office_project_control_settings SET planned_start=?,planned_end=?,actual_start=?,actual_end=?,scope_note=?,revision=?,operator_id=?,updated_at=? WHERE project_id=?')->execute([...$values,$project]);else $this->db->prepare('INSERT INTO office_project_control_settings(planned_start,planned_end,actual_start,actual_end,scope_note,revision,operator_id,updated_at,project_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([...$values,$project]);$this->audit($project,'project_control_saved',null,['before'=>$old,'dates'=>$dates,'scope_note'=>$note]);});
  }
  public function milestones(int $project):array{$this->authorize($project);$q=$this->db->prepare('SELECT * FROM office_project_control_milestones WHERE project_id=? ORDER BY planned_date,id');$q->execute([$project]);return $q->fetchAll(PDO::FETCH_ASSOC);}
  public function milestone(int $project,?int $id,int $revision,array $input,string $today):int{
    $title=self::text($input['title']??null,200);$date=self::date($input['planned_date']??null);$actual=self::date($input['actual_date']??null,true);if($actual&&$actual>$today)throw new \InvalidArgumentException('Een mijlpaal kan niet in de toekomst voltooid zijn.');$target=($input['target_percent']??'')===''?null:self::percent($input['target_percent']);$key=self::text($input['command_key']??null,64);if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new \InvalidArgumentException('Ongeldige opdracht.');
    return $this->transaction($project,function()use($project,$id,$revision,$title,$date,$actual,$target,$key){$old=null;if($id!==null){foreach($this->milestones($project) as $m)if((int)$m['id']===$id)$old=$m;if(!$old||(int)$old['revision']!==$revision||(int)$old['archived']!==0)throw new \DomainException('Mijlpaal gewijzigd of niet beschikbaar.');}
      $points=[];foreach($this->milestones($project) as $m)if((int)$m['archived']===0&&(int)$m['id']!==($id??0)&&$m['target_units']!==null)$points[$m['planned_date']]=(int)$m['target_units'];if($target!==null){if(isset($points[$date])&&$points[$date]!==$target)throw new \DomainException('Eén planningspercentage per datum is toegestaan.');$points[$date]=$target;}ksort($points);$previous=0;foreach($points as $p){if($p<$previous)throw new \DomainException('Geplande voortgang mag niet afnemen tussen mijlpalen.');$previous=$p;}
      if($id!==null)$this->db->prepare('UPDATE office_project_control_milestones SET title=?,planned_date=?,actual_date=?,target_units=?,revision=revision+1,operator_id=?,updated_at=? WHERE id=? AND project_id=?')->execute([$title,$date,$actual,$target,$this->actor,gmdate('c'),$id,$project]);else{$this->db->prepare('INSERT INTO office_project_control_milestones(project_id,title,planned_date,actual_date,target_units,command_key,operator_id,updated_at) VALUES(?,?,?,?,?,?,?,?)')->execute([$project,$title,$date,$actual,$target,$key,$this->actor,gmdate('c')]);$id=(int)$this->db->lastInsertId();}$this->audit($project,'milestone_saved',$id,['before'=>$old,'title'=>$title,'planned_date'=>$date,'actual_date'=>$actual,'target_units'=>$target]);return $id;});
  }
  public function archive(int $project,int $id,int $revision,string $reason):void{$reason=self::text($reason);$this->transaction($project,function()use($project,$id,$revision,$reason){$q=$this->db->prepare('UPDATE office_project_control_milestones SET archived=1,revision=revision+1,operator_id=?,updated_at=? WHERE project_id=? AND id=? AND revision=? AND archived=0');$q->execute([$this->actor,gmdate('c'),$project,$id,$revision]);if($q->rowCount()!==1)throw new \DomainException('Mijlpaal gewijzigd.');$this->audit($project,'milestone_archived',$id,['reason'=>$reason]);});}
  public function progress(int $project):array{$this->authorize($project);$q=$this->db->prepare('SELECT * FROM office_project_control_progress WHERE project_id=? ORDER BY measured_date DESC,id DESC');$q->execute([$project]);return $q->fetchAll(PDO::FETCH_ASSOC);}
  public function measure(int $project,int $latestId,array $input,string $today):int{
    $date=self::date($input['measured_date']??null);if($date>$today)throw new \InvalidArgumentException('Een meting kan niet in de toekomst liggen.');$basis=$input['basis']??'';if(!in_array($basis,['percent','dwellings'],true))throw new \InvalidArgumentException('Kies de meetgrondslag.');$ref=self::text($input['evidence_reference']??null);$key=self::text($input['command_key']??null,64);if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new \InvalidArgumentException('Ongeldige meetopdracht.');
    return $this->transaction($project,function()use($project,$latestId,$input,$date,$basis,$ref,$key){$rows=$this->progress($project);if((int)($rows[0]['id']??0)!==$latestId)throw new \DomainException('Er is een nieuwere voortgangsmeting. Controleer opnieuw.');$done=null;$total=null;if($basis==='dwellings'){$q=$this->db->prepare('SELECT expected_dwelling_count FROM office_project_dwelling_targets WHERE project_id=?');$q->execute([$project]);$total=self::number($q->fetchColumn(),1,1000000);$done=self::number($input['completed_units']??null,0,$total);$percent=intdiv($done*10000+intdiv($total,2),$total);}else $percent=self::percent($input['percent']??null);
      $this->db->prepare('INSERT INTO office_project_control_progress(project_id,measured_date,basis,completed_units,total_units,percent_units,evidence_reference,command_key,operator_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$project,$date,$basis,$done,$total,$percent,$ref,$key,$this->actor,gmdate('c')]);$id=(int)$this->db->lastInsertId();$this->audit($project,'progress_measured',$id,['basis'=>$basis,'measured_date'=>$date,'evidence_reference'=>$ref]);return $id;});
  }
  public function forecast(int $project):?array{$this->authorize($project);if(!$this->finance())return null;$q=$this->db->prepare('SELECT * FROM office_project_control_forecasts WHERE project_id=?');$q->execute([$project]);return $q->fetch(PDO::FETCH_ASSOC)?:null;}
  public function forecastSave(int $project,int $revision,array $input,string $today):void{
    if(!$this->finance(true))throw new \DomainException('Finance-beheer is vereist voor een kostenprognose.');$date=self::date($input['as_of']??null);if($date>$today)throw new \InvalidArgumentException('Prognosedatum ligt in de toekomst.');$amounts=[];foreach(['direct','labor','overhead'] as $key)$amounts[]=self::cents($input[$key]??null);$ref=self::text($input['evidence_reference']??null);
    $this->transaction($project,function()use($project,$revision,$date,$amounts,$ref){$old=$this->forecast($project);if((int)($old['revision']??0)!==$revision)throw new \DomainException('De kostenprognose is gewijzigd.');$values=[...$amounts,$ref,$date,$revision+1,$this->actor,gmdate('c')];if($old)$this->db->prepare('UPDATE office_project_control_forecasts SET direct_cents=?,labor_cents=?,overhead_cents=?,evidence_reference=?,as_of=?,revision=?,operator_id=?,updated_at=? WHERE project_id=?')->execute([...$values,$project]);else $this->db->prepare('INSERT INTO office_project_control_forecasts(direct_cents,labor_cents,overhead_cents,evidence_reference,as_of,revision,operator_id,updated_at,project_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([...$values,$project]);$this->audit($project,'cost_forecast_saved',null,['before'=>$old,'amounts'=>$amounts,'as_of'=>$date,'evidence_reference'=>$ref]);});
  }
  public function parties(int $project,string $role):array{
    $this->authorize($project);if(!in_array($role,['contracting_party','communication_contact'],true))throw new \InvalidArgumentException('Ongeldige projectrol.');$q=$this->db->prepare("SELECT assignment_type,assignment_id,party_role,relation_id FROM office_crm_assignment_parties WHERE assignment_type IN ('project','office_project') AND assignment_id=? AND party_role=? ORDER BY assignment_type,relation_id");$q->execute([(string)$project,$role]);return $q->fetchAll(PDO::FETCH_ASSOC);
  }
  public function party(int $project,string $role,int $relation,string $hash):void{
    if(getenv('OFFICE_CRM_RELATIONS_WRITE_ENABLED')!=='enabled')throw new \DomainException('CRM-beheer is niet actief.');$this->transaction($project,function()use($project,$role,$relation,$hash){$old=$this->parties($project,$role);if(!hash_equals(hash('sha256',json_encode($old,JSON_THROW_ON_ERROR)),$hash))throw new \DomainException('Projectrelatie gewijzigd. Controleer opnieuw.');$q=$this->db->prepare("SELECT 1 FROM office_crm_relations WHERE id=? AND status='active'");$q->execute([$relation]);if(!$q->fetchColumn())throw new \DomainException('Kies een actieve relatie.');$this->db->prepare("DELETE FROM office_crm_assignment_parties WHERE assignment_type IN ('project','office_project') AND assignment_id=? AND party_role=?")->execute([(string)$project,$role]);$this->db->prepare('INSERT INTO office_crm_assignment_parties(assignment_type,assignment_id,party_role,relation_id) VALUES(?,?,?,?)')->execute(['office_project',(string)$project,$role,$relation]);$this->audit($project,'project_party_set',null,['before'=>$old,'role'=>$role,'relation_id'=>$relation]);});
  }

}
